import {DEFAULT_NAVIGATION,menuHTML,migrateNavigation} from './site-navigation.mjs';
const json=(v,s=200)=>new Response(JSON.stringify(v),{status:s,headers:{'Content-Type':'application/json','Cache-Control':'no-store'}});
export async function navigationSettings(env){const row=await env.DB.prepare('SELECT value FROM site_settings WHERE key = ?').bind('navigation').first();if(!row)return {items:DEFAULT_NAVIGATION,revision:0,batchVersion:1};const value=JSON.parse(row.value);const data=value.batchVersion?value:{...value,items:migrateNavigation(value.items),batchVersion:1};Object.defineProperty(data,'storedValue',{value:row.value,enumerable:false});return data;}
export async function navigationRoutes(request,env,url,isAdmin){if(!['/api/navigation','/api/admin/navigation'].includes(url.pathname))return null;const owner=url.pathname.startsWith('/api/admin/');if(owner&&!isAdmin(request))return json({error:'Owner sign-in required'},403);if(!env.DB)return json({error:'Menu storage unavailable'},503);if(request.method==='GET')return json(await navigationSettings(env));if(!owner||request.method!=='POST')return json({error:'Method not allowed'},405);if(request.headers.get('Origin')!==url.origin)return json({error:'Invalid origin'},403);
try{const raw=await request.text();if(raw.length>80000)throw Error('Menus are too large');const v=JSON.parse(raw),prior=await navigationSettings(env);if(v.revision!==prior.revision)return json({error:'Menus changed elsewhere. Reload before saving.'},409);if(!Array.isArray(v.items)||v.items.length>20)throw Error('Use up to 20 main menu items');const label=s=>typeof s==='string'&&s.trim().length>0&&s.length<=100;const link=s=>typeof s==='string'&&/^\/satin(?:\/[a-z0-9-]+)*(?:[?#][^<>"'\s]*)?$/.test(s)&&s.length<=300;const keys=new Set();for(const m of v.items){if(!/^[a-z0-9-]{1,60}$/.test(m.key)||keys.has(m.key)||!label(m.label)||!link(m.href)||typeof m.active!=='boolean'||!Array.isArray(m.groups)||m.groups.length>8)throw Error('Check menu name and page link');keys.add(m.key);for(const g of m.groups){if(!label(g.label)||!Array.isArray(g.links)||g.links.length>60)throw Error('Check submenu group');for(const l of g.links)if(!label(l.label)||!link(l.href)||typeof l.active!=='boolean')throw Error('Check submenu name and link');}}const value={items:v.items,revision:prior.revision+1,batchVersion:1};const now=new Date().toISOString();const r=prior.revision?await env.DB.prepare('UPDATE site_settings SET value = ?,updated_at = ? WHERE key = ? AND value = ?').bind(JSON.stringify(value),now,'navigation',prior.storedValue||JSON.stringify(prior)).run():await env.DB.prepare('INSERT INTO site_settings (key,value,updated_at) VALUES (?,?,?) ON CONFLICT(key) DO NOTHING').bind('navigation',JSON.stringify(value),now).run();if(!r.meta.changes)return json({error:'Menus changed elsewhere. Reload.'},409);return json(value);}catch(e){return json({error:e.message},400);}}
export async function renderNavigation(response,request,env){if(!env.DB||!response.ok||!response.headers.get('Content-Type')?.includes('text/html'))return response;let html=await response.text();try{const data=await navigationSettings(env);const lang=new URL(request.url).pathname.match(/^\/satin\/(fa|fr|es)(?:\/|$)/)?.[1]||'en';html=html.replace(/<nav class="nav" aria-label="Main">[\s\S]*?<\/nav>/,'<nav class="nav" aria-label="Main">'+menuHTML(data.items,false,lang)+'</nav>');html=html.replace(/(<button[^>]*data-cart[^>]*>)/,`<a class="header-login" href="/satin/${lang==='en'?'':lang+'/'}login/">${{en:'Log in',fa:'ورود',fr:'Connexion',es:'Iniciar sesión'}[lang]}</a>$1`);html=html.replace('</head>','<script type="application/json" data-navigation-bootstrap>'+JSON.stringify(data).replace(/</g,'\\u003c')+'</script></head>');}catch(e){console.error('Menu rendering failed',e.message);}const headers=new Headers(response.headers);headers.delete('Content-Length');return new Response(html,{status:response.status,headers});}
